"""Grammars for structured replies: llama.cpp GBNF for BAXY's smallest closed validators, and the JSON-schema
bounds the grammar compiler can take.
"""

from __future__ import annotations

import json
from typing import Any


# The JSON-schema grammar generated by llama.cpp permits leading whitespace.
# Gemma sometimes spent the whole token budget there, so the same three-value
# contract is expressed directly as compact GBNF. This changes serialization,
# not the set of language decisions that the model is allowed to return.
_RESPONSE_LANGUAGE_GRAMMAR = (
    'root ::= "{" "\\"language\\"" ":" "\\"" language "\\"" "}"\n'
    'language ::= "es" | "en" | "mixed"'
)


def _gbnf_terminal(value: str) -> str:
    """Encode exact UTF-8 text as one llama.cpp GBNF string terminal."""

    return json.dumps(value, ensure_ascii=False)


def _gbnf_json_enum(values: object) -> str | None:
    """Return terminals for an exact, non-empty JSON string enum."""

    if (
        not isinstance(values, list)
        or not values
        or any(not isinstance(value, str) for value in values)
        or len(set(values)) != len(values)
    ):
        return None
    return " | ".join(
        _gbnf_terminal(json.dumps(value, ensure_ascii=False)) for value in values
    )


# Ronda 20 P5 (pasada r18 v3-27): clipboard.write.text declares text.maxLength=65 536; llama.cpp's JSON-schema to
# GBNF converter wrote it as `char{0,65536}` and its grammar parser refused any repetition above 2 000 («number of
# repetitions exceeds sane defaults»), a 4xx in 47 ms that ended the turn as «on this PC». The wire copy of a schema
# carries no length or count bound above this ceiling; the full schema still validates the answer (here and in the
# Kernel), and max_tokens bounds what the model can write anyway.
GRAMMAR_REPETITION_CEILING = 2000
_GRAMMAR_REPETITION_BOUNDS = ("maxLength", "minLength", "maxItems", "minItems")


def grammar_safe_schema(schema: object) -> object:
    """``schema`` with every length or count bound above GRAMMAR_REPETITION_CEILING taken out, at any depth. A schema
    with none is returned as the very same object (byte for byte the same on the wire)."""

    if isinstance(schema, list):
        items = [grammar_safe_schema(item) for item in schema]
        return schema if all(new is old for new, old in zip(items, schema)) else items
    if not isinstance(schema, dict):
        return schema
    changed = False
    safe: dict[str, Any] = {}
    for key, value in schema.items():
        if (
            key in _GRAMMAR_REPETITION_BOUNDS and isinstance(value, int) and not isinstance(value, bool)
            and value > GRAMMAR_REPETITION_CEILING
        ):
            changed = True
            continue
        # «properties» maps names to schemas: a property may be called like a bound and is never one.
        new = grammar_safe_schema(value) if isinstance(value, (dict, list)) else value
        changed = changed or new is not value
        safe[key] = new
    return safe if changed else schema


def _grammar_safe_payload(payload: dict[str, Any]) -> dict[str, Any]:
    """The wire copy of ``payload`` whose response_format schema passes grammar_safe_schema; the same payload when it
    needs nothing (never mutated: the full schema is kept for the validators and the retries)."""

    response_format = payload.get("response_format")
    envelope = response_format.get("json_schema") if isinstance(response_format, dict) else None
    schema = envelope.get("schema") if isinstance(envelope, dict) else None
    if not isinstance(schema, dict):
        return payload
    safe = grammar_safe_schema(schema)
    if safe is schema:
        return payload
    return {**payload, "response_format": {**response_format, "json_schema": {**envelope, "schema": safe}}}


def _compact_structured_grammar(payload: dict[str, Any]) -> str | None:
    """Compile BAXY's smallest closed validators to whitespace-free GBNF.

    llama.cpp's generic JSON-schema converter deliberately permits formatting
    whitespace after nearly every token. On a greedy autoregressive decoder,
    those spaces and newlines are additional model passes. The wire grammar
    below preserves each validator's keys, order and closed values while making
    its serialization compact. The richer primary turn decision deliberately
    keeps its original JSON Schema because its learned formatting context
    affects Gemma's classification quality. Any schema drift falls back to the
    original response_format instead of being guessed.
    """

    response_format = payload.get("response_format")
    if (
        not isinstance(response_format, dict)
        or response_format.get("type") != "json_schema"
    ):
        return None
    envelope = response_format.get("json_schema")
    if not isinstance(envelope, dict) or envelope.get("strict") is not True:
        return None
    name = envelope.get("name")
    schema = envelope.get("schema")
    if (
        not isinstance(schema, dict)
        or schema.get("type") != "object"
        or schema.get("additionalProperties") is not False
    ):
        return None
    properties = schema.get("properties")
    required = schema.get("required")
    if not isinstance(properties, dict) or not isinstance(required, list):
        return None

    if name == "baxy_semantic_effect_guard":
        expected = ["request_type", "effect_count"]
        if list(properties) != expected or required != expected:
            return None
        request_type_schema = properties.get("request_type")
        effect_count_schema = properties.get("effect_count")
        if (
            not isinstance(request_type_schema, dict)
            or request_type_schema.get("type") != "string"
            or not isinstance(effect_count_schema, dict)
            or effect_count_schema.get("type") != "string"
        ):
            return None
        request_types = _gbnf_json_enum(request_type_schema.get("enum"))
        effect_counts = _gbnf_json_enum(effect_count_schema.get("enum"))
        if request_types is None or effect_counts is None:
            return None
        return "\n".join(
            [
                (
                    "root ::= "
                    + _gbnf_terminal('{"request_type":')
                    + " request-type "
                    + _gbnf_terminal(',"effect_count":')
                    + " effect-count "
                    + _gbnf_terminal("}")
                ),
                f"request-type ::= {request_types}",
                f"effect-count ::= {effect_counts}",
            ]
        )
    return None
